mapper.select:
SELECT analytics_user_id, COUNT(*) AS event_count, MIN(occurred_at) AS first_seen, MAX(occurred_at) AS last_seen, MAX(platform) AS platform FROM analytics_event WHERE occurred_at >= #{from} AND occurred_at < #{to} AND analytics_user_id IS NOT NULL AND analytics_user_id <> ''
AND LOWER(analytics_user_id) LIKE CONCAT('%', #{search}, '%')
GROUP BY analytics_user_id ORDER BY last_seen DESC LIMIT #{limit} OFFSET #{offset}
